namespace ghidra.program.model.data.ISF;

using ghidra.program.model.data;
using ghidra.program.model.data.ISF.AbstractIsfWriter;

public class IsfDataTypeBitField : AbstractIsfObject {

	public string kind;
	public Integer bit_length;
	public Integer bit_position;
	public IsfObject type;

	/* @Exclude */
	public Integer bit_offset;
	/* @Exclude */
	private int storage_size;

	public IsfDataTypeBitField(BitFieldDataType bf, int componentOffset, IsfObject typeObj) : base(bf)
    {
		kind = IsfUtilities.getKind(bf);
		bit_length = bf.getBitSize();
		bit_offset = bf.getBitOffset();
		bit_position = componentOffset % 4 * 8 + bit_offset;
		type = typeObj;

		storage_size = bf.getStorageSize();
	}

}
